CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), nom TEXT NOT NULL, pays CHAR(2) NOT NULL, telephone_international TEXT UNIQUE NOT NULL, email TEXT UNIQUE, mot_de_passe_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ledger (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), sens TEXT NOT NULL CHECK (sens IN ('credit','debit')), montant INTEGER NOT NULL CHECK (montant >= 0), type TEXT NOT NULL, reference TEXT UNIQUE NOT NULL, statut TEXT NOT NULL DEFAULT 'posted', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transfers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sender_ledger_id BIGINT REFERENCES ledger(id), recipient_ledger_id BIGINT REFERENCES ledger(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recharges (reference TEXT PRIMARY KEY, ebilling_bill_id TEXT, statut TEXT NOT NULL CHECK (statut IN ('created','pending','paid','failed','expired','ambiguous')), montant INTEGER NOT NULL, frais INTEGER NOT NULL DEFAULT 0, user_id UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), paid_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS withdrawals (reference TEXT PRIMARY KEY, shap_reference TEXT, statut TEXT NOT NULL DEFAULT 'pending', montant INTEGER NOT NULL, frais INTEGER NOT NULL DEFAULT 0, user_id UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_attempts (id BIGSERIAL PRIMARY KEY, telephone TEXT NOT NULL, success BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_attempts_phone_time ON login_attempts(telephone, created_at);
